'use strict';
// La caché nunca contiene contraseñas, tokens CSRF ni cookies. Las escrituras offline son borradores pendientes.
const offlineDb=new Promise((resolve,reject)=>{const request=indexedDB.open('aurea-device',1);request.onupgradeneeded=()=>{request.result.createObjectStore('cache');request.result.createObjectStore('outbox',{keyPath:'key'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});
async function localRequest(store,mode,action){const db=await offlineDb;return new Promise((resolve,reject)=>{const transaction=db.transaction(store,mode),request=action(transaction.objectStore(store));let value;request.onsuccess=()=>value=request.result;transaction.oncomplete=()=>resolve(value);transaction.onerror=()=>reject(transaction.error);});}
const pending=()=>localRequest('outbox','readonly',s=>s.getAll()).then(rows=>rows.filter(r=>r.userId===appState.user?.id));
const coreLoad=load;
load=async function(){await coreLoad();if(appState._cartUser!==appState.user.id){appState._cartUser=appState.user.id;try{const draft=JSON.parse(sessionStorage.getItem('aurea-cart-'+appState.user.id)||'null');if(draft&&Array.isArray(draft.cart)){appState.cart=draft.cart.filter(i=>data().products.some(p=>p.id===i.productId)&&Number.isFinite(i.qty)&&i.qty>0);appState.customerId=data().customers.some(c=>c.id===draft.customerId)?draft.customerId:'';}}catch{}}try{await localRequest('cache','readwrite',s=>s.put({data:data(),user:appState.user,revision:appState.revision,today:appState.today,expires:Date.now()+8*3600000,savedAt:new Date().toISOString()},'current'));}catch{toast('No se pudo actualizar la copia offline; los datos del servidor están guardados.');}};
const coreMutate=mutate;
mutate=async function(command,body,form){try{const result=await coreMutate(command,body,form);try{localStorage.setItem('aurea-revision',JSON.stringify({userId:appState.user.id,revision:result.revision,time:Date.now()}));}catch{}if(command==='sale.create')sessionStorage.removeItem('aurea-cart-'+appState.user.id);return result;}catch(e){if(!e.status&&appState.offline&&form._request){const draft={key:form._request.key,revision:form._request.revision,command,body,userId:appState.user.id,createdAt:new Date().toISOString()};await localRequest('outbox','readwrite',s=>s.put(draft));e.message='Guardado en este dispositivo como PENDIENTE. No es una venta ni un pago confirmado. Revisa la cola al recuperar conexión.';showOfflineBanner();}throw e;}};
extraUI.offline=async function(){await localRequest('cache','readonly',s=>s.get('current')).then(cache=>{if(!cache||cache.expires<Date.now()){document.querySelector('#app').innerHTML=empty('No hay una sesión offline vigente','Conecta el servidor de Áurea e inicia sesión para continuar.');return;}appState.user=cache.user;appState.data=cache.data;appState.revision=cache.revision;appState.today=cache.today;appState.initialized=true;appState.offline=true;appState.start=cache.today;appState.end=cache.today;appState.route=allowed('pos')?'pos':Object.keys(labels).find(r=>allowed(r))||'inicio';render();showOfflineBanner();}).catch(()=>{document.querySelector('#app').innerHTML=empty('No pudimos leer la copia local','Inicia el servidor de Áurea para continuar.');});return true;};
async function showOfflineBanner(){if(!appState.user)return;const rows=await pending();let banner=document.querySelector('#offline-banner');if(!banner){banner=document.createElement('div');banner.id='offline-banner';banner.className='offline-banner';document.querySelector('.workspace')?.prepend(banner);}if(banner){banner.hidden=!appState.offline&&!rows.length;banner.innerHTML=`<span>${appState.offline?'Sin conexión · copia local':'Conexión disponible'} · ${rows.length} operaciones pendientes de confirmar</span><div class="row">${pButton('Reconectar','reconnect','text')}${pButton('Revisar pendientes','outbox','text')}</div>`;}}
const parityAction=extraUI.action;
extraUI.action=async function(a,t){if(a==='x-reconnect'){const session=await api('/api/session');if(!session.user){appState.user=null;authView();return;}if(session.user.id!==appState.user.id)throw Error('Inicia sesión con el usuario de esta copia local.');appState.csrf=session.csrf;await load();render();toast('Conexión y datos actualizados.');return;}if(a==='x-outbox'){const rows=await pending();modal('Operaciones pendientes',`<div class="info-strip">Estos registros no están confirmados en el servidor. La sincronización valida sesión, permisos, stock, saldos y revisión.</div>${rows.length?table(['Fecha','Operación','Estado',''],rows.map(r=>`<tr><td>${fmtDate(r.createdAt)}</td><td>${esc(r.command)}</td><td>Pendiente</td><td>${pButton('Revisar y enviar','pending-'+r.key,'text')}${pButton('Descartar','discard-'+r.key,'text')}</td></tr>`)):empty('Sin operaciones pendientes','Tus registros confirmados están en el servidor.')}`);return;}
if(a.startsWith('x-pending-')){const key=a.slice(10),row=(await pending()).find(x=>x.key===key);if(!row)throw Error('No se encontró el borrador.');const online=await api('/api/session');if(!online.user||online.user.id!==row.userId)throw Error('Inicia sesión con el usuario que creó el pendiente.');appState.csrf=online.csrf;await coreLoad();if(appState.user.id!==row.userId)throw Error('Inicia sesión con el usuario que creó este pendiente.');modal('Revisar antes de enviar',pForm('offline-send-form',`<p><strong>${esc(row.command)}</strong> · ${fmtDate(row.createdAt)}</p><pre class="draft-preview">${esc(JSON.stringify(row.body,null,2))}</pre><div class="info-strip">Se enviará con el estado actual del servidor. Si ya había sido confirmado, su identificador impedirá duplicarlo.</div>`,'Confirmar envío del pendiente',`data-key="${key}"`));return;}
if(a.startsWith('x-discard-')){const key=a.slice(10);modal('Descartar borrador pendiente',pForm('offline-discard-form','<p style="margin-bottom:20px">Se quitará de esta cola local. Esta acción no anula operaciones que ya estén registradas en el servidor.</p>','Descartar borrador',`data-key="${key}"`));return;}
return parityAction(a,t);};
const paritySubmit=extraUI.submit;
extraUI.submit=async function(form,v){if(form.id==='offline-send-form'){const row=(await pending()).find(x=>x.key===form.dataset.key);if(!row)throw Error('Pendiente no encontrado.');await api('/api/command',{method:'POST',headers:{'Idempotency-Key':row.key},body:JSON.stringify({command:row.command,body:row.body,revision:appState.revision})});await localRequest('outbox','readwrite',s=>s.delete(row.key));if(row.command==='sale.create'){appState.cart=[];sessionStorage.removeItem('aurea-cart-'+appState.user.id);}await load();closeModal();render();showOfflineBanner();toast('Operación confirmada por el servidor.');return null;}
if(form.id==='offline-discard-form'){await localRequest('outbox','readwrite',s=>s.delete(form.dataset.key));closeModal();showOfflineBanner();toast('Borrador descartado.');return null;}return paritySubmit(form,v);};
const parityDecorate=extraUI.decorate;
extraUI.decorate=function(){parityDecorate();showOfflineBanner();if(appState.route==='pos'){try{sessionStorage.setItem('aurea-cart-'+appState.user.id,JSON.stringify({cart:appState.cart,customerId:appState.customerId}));}catch{}}};
const cachedAuth=authView;
authView=function(){if(!appState.user)localRequest('cache','readwrite',s=>s.delete('current')).catch(()=>{});cachedAuth();for(const field of document.querySelectorAll('.login-form input[type=password]')){if(field.name==='setupToken')continue;field.setAttribute('aria-label',field.closest('.field').querySelector('span').textContent);field.closest('.field').insertAdjacentHTML('beforeend',pButton('Mostrar','eye-'+field.name,'text'));}};
window.addEventListener('online',showOfflineBanner);
window.addEventListener('offline',()=>{appState.offline=true;showOfflineBanner();});
document.addEventListener('input',e=>{if(e.target.matches('[data-cart-qty],[data-unit-price],[data-discount]'))setTimeout(()=>{if(appState.user)try{sessionStorage.setItem('aurea-cart-'+appState.user.id,JSON.stringify({cart:appState.cart,customerId:appState.customerId}));}catch{}},0);});
async function refreshRemote(){if(!appState.user||appState.offline||document.visibilityState!=='visible'||document.querySelector('#dialog').open||document.activeElement?.matches('input,textarea,select')||['config','usuarios'].includes(appState.route))return;const previous=appState.revision;try{await load();if(appState.revision!==previous)render();}catch(e){if(e.status===401){appState.user=null;appState.cart=[];authView();toast('La sesión terminó. Inicia sesión nuevamente.');}else showOfflineBanner();}}
window.addEventListener('focus',refreshRemote);setInterval(refreshRemote,30000);
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('/service-worker.js').catch(()=>{});

document.addEventListener('click',e=>{if(e.target.closest('[data-add],[data-remove]'))setTimeout(()=>{if(appState.user)try{sessionStorage.setItem('aurea-cart-'+appState.user.id,JSON.stringify({cart:appState.cart,customerId:appState.customerId}));}catch{}},0);});

window.addEventListener('storage',e=>{if(e.key==='aurea-revision'&&appState.user){try{const update=JSON.parse(e.newValue);if(update.userId===appState.user.id&&update.revision!==appState.revision)refreshRemote();}catch{}}});
